/* ============ SITE CODE (no need to edit) ============ */
const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const btn = (url, label, cls) => url
  ? `<a class="btn ${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`
  : `<span class="btn ${cls} is-disabled" aria-disabled="true" title="Link coming soon">${label}</span>`;
const thumb = p => p.image2 ? `<div class="thumb shots"><img src="${esc(p.image)}" alt="S² chatbot home screen"><img src="${esc(p.image2)}" alt="S² chatbot answering a malware question"></div>` :  `<div class="thumb">${p.image ? `<img src="${esc(p.image)}" alt="${esc(p.name)} screenshot" loading="lazy">` : esc(p.name.slice(0, 2))}</div>`;
const tags = p => p.tech.map(t => `<span class="tag">${esc(t)}</span>`).join(" ");
const info = p => `<div class="body"><span class="status">Status: ${esc(p.status)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="chips">${tags(p)}</div><div class="actions">${btn(p.demo, "View Project", "primary")}${btn(p.github, "GitHub", "ghost")}</div></div>`;

document.getElementById("project-grid").innerHTML =
  PROJECTS.map(p => `<article class="glass card${p.featured ? " featured wide" : ""}">${thumb(p)}${info(p)}</article>`).join("") +
  `<div class="glass card soon"><p>More Projects Coming Soon...</p></div>`;

const links = [
  ["Email", "email", v => "mailto:" + v], ["GitHub", "github", v => v],
  ["LinkedIn", "linkedin", v => v], ["Location", "location", null]
].filter(([l, k]) => CONFIG[k]);
document.getElementById("contact-list").innerHTML = links.map(([l, k, f]) => {
  const v = CONFIG[k];
  return `<li><strong>${l}</strong>${v ? (f ? `<a href="${esc(f(v))}">${esc(v)}</a>` : `<span>${esc(v)}</span>`) : `<span class="muted">[Add ${l}]</span>`}</li>`;
}).join("");
document.getElementById("footer-contact").innerHTML = CONFIG.email ? `<li><a href="mailto:${esc(CONFIG.email)}">${esc(CONFIG.email)}</a></li>` : "";
document.getElementById("footer-social").innerHTML = links.filter(x => x[2] && x[1] !== "email").map(([l, k, f]) =>
  `<li>${CONFIG[k] ? `<a href="${esc(f(CONFIG[k]))}">${l}</a>` : `<a href="#contact">${l}</a>`}</li>`).join("");

/* Profile photo */
const box = document.getElementById("photo-box"), upBtn = document.getElementById("up-btn"), upFile = document.getElementById("up-file");
const setPhoto = src => { box.innerHTML = `<img src="${esc(src)}" alt="Murugesa profile photo">`; upBtn.textContent = "Change photo"; };
let saved = null;
try { saved = localStorage.getItem("murugesa-photo"); } catch (e) {}
const upReset = document.getElementById("up-reset");
if (saved) { setPhoto(saved); upReset.hidden = false; } else if (CONFIG.photo) setPhoto(CONFIG.photo);
upReset.addEventListener("click", () => { try { localStorage.removeItem("murugesa-photo"); } catch (e) {} if (CONFIG.photo) setPhoto(CONFIG.photo); else box.innerHTML = '<span class="photo-ph">M</span>'; upReset.hidden = true; });
upBtn.addEventListener("click", () => upFile.click());
upFile.addEventListener("change", () => {
  const f = upFile.files[0]; if (!f) return;
  const r = new FileReader();
  r.onload = () => {
    const im = new Image();
    im.onload = () => {
      const n = Math.min(im.width, im.height), c = document.createElement("canvas");
      c.width = c.height = 600;
      c.getContext("2d").drawImage(im, (im.width - n) / 2, (im.height - n) / 2, n, n, 0, 0, 600, 600);
      const d = c.toDataURL("image/jpeg", .85);
      setPhoto(d); upReset.hidden = false;
      try { localStorage.setItem("murugesa-photo", d); } catch (e) {}
    };
    im.src = r.result;
  };
  r.readAsDataURL(f);
  upFile.value = "";
});

document.getElementById("contact-form").addEventListener("submit", e => {
  e.preventDefault();
  const f = e.target, s = document.getElementById("form-status");
  if (!f.checkValidity()) { s.textContent = "Please fill in your name, a valid email and a message."; return; }
  if (!CONFIG.email) { s.textContent = "Email is not set up yet."; return; }
  const body = `${f.message.value}\n\nFrom: ${f.name.value} (${f.email.value})`;
  location.href = `mailto:${CONFIG.email}?subject=${encodeURIComponent("Portfolio message from " + f.name.value)}&body=${encodeURIComponent(body)}`;
  s.textContent = "Opening your email app to send the message.";
});
(function(){
  const l=document.getElementById("loader");let gone=false;
  const hide=()=>{if(gone)return;gone=true;l.classList.add("done");document.body.classList.remove("loading");setTimeout(()=>l.remove(),900)};
  l.addEventListener("click",hide);
  addEventListener("keydown",hide,{once:true});
  setTimeout(hide,4200);
})();
